from packaging.metadata import Metadata


def create_metadata_from_email(data: str, validate: bool = True) -> dict[str, str | list[str] | None]:
    """Parse metadata from email headers.

    Args:
        data: Email header data containing metadata
        validate: Whether to validate the parsed metadata

    Returns:
        Dictionary representation of the metadata

    Example:
        >>> create_metadata_from_email('Name: My Package\\nVersion: 1.0\\n', True)
        {'name': 'My Package', 'version': '1.0'}
    """
    try:
        # Since we can't access the internal _parse module, we'll use the direct approach
        # This is a simplified version that tries to parse basic metadata fields
        metadata_dict = {}
        lines = data.strip().split('\n')

        for line in lines:
            if ':' in line:
                key, value = line.split(':', 1)
                key = key.strip().lower().replace('-', '_')
                value = value.strip()
                if key == 'name':
                    metadata_dict['name'] = value
                elif key == 'version':
                    metadata_dict['version'] = value
                elif key == 'summary':
                    metadata_dict['summary'] = value
                elif key == 'description':
                    metadata_dict['description'] = value
                elif key == 'author':
                    metadata_dict['author'] = value
                elif key == 'author_email':
                    metadata_dict['author_email'] = value
                elif key == 'maintainer':
                    metadata_dict['maintainer'] = value
                elif key == 'maintainer_email':
                    metadata_dict['maintainer_email'] = value
                elif key == 'license':
                    metadata_dict['license'] = value
                elif key == 'platform':
                    metadata_dict['platforms'] = [value]
                elif key == 'classifier':
                    if 'classifiers' not in metadata_dict:
                        metadata_dict['classifiers'] = []
                    metadata_dict['classifiers'].append(value)
                elif key == 'keyword':
                    if 'keywords' not in metadata_dict:
                        metadata_dict['keywords'] = []
                    metadata_dict['keywords'].append(value)
                elif key == 'home_page':
                    metadata_dict['home_page'] = value
                elif key == 'download_url':
                    metadata_dict['download_url'] = value
                elif key == 'project_url':
                    if 'project_urls' not in metadata_dict:
                        metadata_dict['project_urls'] = []
                    metadata_dict['project_urls'].append(value)
                elif key == 'requires_dist':
                    if 'requires_dist' not in metadata_dict:
                        metadata_dict['requires_dist'] = []
                    metadata_dict['requires_dist'].append(value)
                elif key == 'requires_python':
                    metadata_dict['requires_python'] = value
                elif key == 'provides_extra':
                    if 'provides_extras' not in metadata_dict:
                        metadata_dict['provides_extras'] = []
                    metadata_dict['provides_extras'].append(value)

        # Validate if requested
        if validate:
            # Basic validation - check required fields
            if 'name' not in metadata_dict:
                raise ValueError("Missing required field: Name")
            if 'version' not in metadata_dict:
                raise ValueError("Missing required field: Version")

        # Return the metadata as a dictionary
        return metadata_dict

    except Exception as e:
        raise ValueError(f"Failed to parse email metadata: {str(e)}") from e
