def resolve_dependency_groups(
    dependency_groups: dict[str, list[str | dict[str, str]]],
    group1: str | None = None,
    group2: str | None = None,
    group3: str | None = None,
) -> list[str]:
    """Resolve a dependency group to a tuple of requirements, as strings. dependency_groups: the parsed contents of the [dependency-groups] table from pyproject.toml. groups: the name of the group(s) to resolve, e.g. resolve_dependency_groups({"backend": ["flask"]}, "backend") -> ["flask"]."""
